#!/usr/bin/env bash
# H2H bundle: DEER-grader adoption + --temperature + head-to-head queue.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing H2H bundle..."
decode "apply_grader_patch.py" << 'B64EOF'

B64EOF
decode "apply_temp_patch.py" << 'B64EOF'

B64EOF
decode "run_queue_h2h.sh" << 'B64EOF'

B64EOF
python apply_grader_patch.py && rm apply_grader_patch.py
python apply_temp_patch.py && rm apply_temp_patch.py
chmod +x run_queue_h2h.sh
echo ""
echo "Installed. Steps:"
echo "  bash run_queue_h2h.sh --dry   # inspect 6 jobs"
echo "  bash run_queue_h2h.sh         # submit"